# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİKDÖRTGENLER PRİZMASININ YÜZEY ALANI VE HACMİ (MAT.7.4.6)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Prizma Modeli (Ayrıtlar: a, b, c)</text>\n  <polygon points="55,195 165,195 165,125 55,125" fill="#dbeafe" stroke="#1d4ed8" stroke-width="2"/>\n  <polygon points="55,125 90,95 200,95 165,125" fill="#bfdbfe" stroke="#1d4ed8" stroke-width="2"/>\n  <polygon points="165,125 200,95 200,165 165,195" fill="#93c5fd" stroke="#1d4ed8" stroke-width="2"/>\n  <text x="110" y="212" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">a (uzunluk)</text>\n  <text x="196" y="188" font-size="11.5" font-weight="bold" fill="#1e40af">b (genişlik)</text>\n  <text x="42" y="162" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">c</text>\n  <text x="220" y="118" font-size="11" fill="#334155">• 6 dikdörtgensel yüz</text>\n  <text x="220" y="140" font-size="11" fill="#334155">• 12 ayrıt (4\'er eş ayrıt)</text>\n  <text x="220" y="162" font-size="11" fill="#334155">• 8 köşe</text>\n  <text x="220" y="184" font-size="11" font-weight="bold" fill="#1d4ed8">Küp: a = b = c</text>\n  <rect x="358" y="48" width="317" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="516" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yüzey Alanı ve Hacim Bağıntıları</text>\n  <text x="374" y="100" font-size="11.5" font-weight="bold" fill="#166534">1. Yüzey Alanı (Kaplama / Boyama / Hediye Paketi):</text>\n  <text x="384" y="120" font-size="12" font-weight="bold" fill="#1e293b">Alan = 2 · (a·b + a·c + b·c)</text>\n  <text x="384" y="138" font-size="11" fill="#334155">• Küpün Yüzey Alanı = 6 · a²</text>\n  <text x="374" y="166" font-size="11.5" font-weight="bold" fill="#166534">2. Hacim (İç Kapasite / Su / Kum / Koli İstifleme):</text>\n  <text x="384" y="186" font-size="12" font-weight="bold" fill="#1e293b">Hacim (V) = Taban Alanı · Yükseklik = a · b · c</text>\n  <text x="384" y="204" font-size="11" fill="#334155">• Küpün Hacmi (V) = a³ = a · a · a</text>\n  <text x="516" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Üstü açık kutuda: Alan = a·b + 2·(a·c + b·c)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HACİM VE SIVI ÖLÇME BİRİMLERİ KÖPRÜSÜ (1 dm³ = 1 L)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Hacim Ölçme Birimleri (1000\'er Değişim)</text>\n  <text x="44" y="102" font-size="12" font-weight="bold" fill="#92400e">m³  ⇄  dm³  ⇄  cm³  ⇄  mm³</text>\n  <text x="44" y="124" font-size="11" fill="#334155">• Aşağı inerken her adımda 1000 ile çarpılır:</text>\n  <text x="54" y="142" font-size="11" font-weight="bold" fill="#334155">1 m³ = 1000 dm³   |   1 dm³ = 1000 cm³</text>\n  <text x="54" y="160" font-size="11" font-weight="bold" fill="#334155">1 cm³ = 1000 mm³</text>\n  <text x="44" y="184" font-size="11" fill="#334155">• Yukarı çıkarken her adımda 1000\'e bölünür:</text>\n  <text x="54" y="202" font-size="11" fill="#334155">5000 cm³ = 5 dm³   |   2500 dm³ = 2,5 m³</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. Sıvı Ölçme Birimleri (10\'ar) ve Köprü</text>\n  <text x="378" y="102" font-size="12" font-weight="bold" fill="#1e40af">L  ⇄  dL  ⇄  cL  ⇄  mL</text>\n  <text x="378" y="124" font-size="11" fill="#334155">• 1 L = 10 dL = 100 cL = 1000 mL</text>\n  <rect x="378" y="138" width="278" height="84" rx="6" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="517" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">ALTIN KÖPRÜ BAĞINTILARI</text>\n  <text x="517" y="178" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b91c1c">1 dm³ = 1 Litre (L) = 1000 mL</text>\n  <text x="517" y="196" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">1 cm³ = 1 Mililitre (mL)</text>\n  <text x="517" y="214" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">1 m³ = 1000 dm³ = 1000 Litre (L)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">GÜNLÜK HAYAT PROBLEMLERİ ÇÖZÜM STRATEJİLERİ (MAT.7.4.6)</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">1. Depo ve Akvaryum (Sıvı)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Ayrıtları cm verilen akvaryumun</text>\n  <text x="40" y="114" font-size="11" fill="#334155">  hacmi cm³ olarak bulunur.</text>\n  <text x="40" y="136" font-size="11" fill="#334155">• 1000\'e bölünerek dm³ = Litre</text>\n  <text x="40" y="152" font-size="11" fill="#334155">  cinsinden su kapasitesi hesaplanır.</text>\n  <text x="40" y="176" font-size="11" font-weight="bold" fill="#166534">Örnek: 50 cm × 40 cm × 30 cm</text>\n  <text x="40" y="194" font-size="11" fill="#334155">V = 60.000 cm³ = 60 dm³ = 60 L</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. Koliye Kutu Yerleştirme</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Büyük kolinin ayrıtları, küçük</text>\n  <text x="260" y="114" font-size="11" fill="#334155">  kutunun eşleşen ayrıtlarına</text>\n  <text x="260" y="130" font-size="11" fill="#334155">  bölünerek sığacak adet bulunur:</text>\n  <text x="260" y="154" font-size="11" font-weight="bold" fill="#1e40af">Adet = V(Büyük) / V(Küçük)</text>\n  <text x="260" y="176" font-size="11" fill="#334155">• Önce tüm ayrıtlar aynı uzunluk</text>\n  <text x="260" y="192" font-size="11" fill="#334155">  birimine (cm veya dm) çevrilir!</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">3. Boyama ve Kaplama (Alan)</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• Oda duvarı veya havuz boyanırken</text>\n  <text x="480" y="114" font-size="11" fill="#334155">  HANGİ YÜZLERİN boyandığına</text>\n  <text x="480" y="130" font-size="11" fill="#334155">  dikkat edilir!</text>\n  <text x="480" y="152" font-size="11" fill="#334155">• Havuzda: Taban + 4 yan yüz</text>\n  <text x="480" y="168" font-size="11" fill="#334155">  (Üst yüz açıktır, çıkarılır).</text>\n  <text x="480" y="190" font-size="11" fill="#334155">• Oda boyamada: Kapı ve pencere</text>\n  <text x="480" y="206" font-size="11" fill="#334155">  alanları toplam alandan düşülür.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
